Let $A \subseteq \mathbb{N}$. The following statements are equivalent.
    \begin{enumerate}
        \item  The set $A$ is dynamically central syndetic.  

        \item 
        There exists a minimal system $(X,T)$, a nonempty, open set $U \subseteq X$, and a point $x \in \overline{U}$ such that $R(x,U) \subseteq A$.


        \item  There exists a subset $B \subseteq A$ such that the point $1_{B \cup \{0\}}$ is uniformly recurrent in the full shift $(\{0, 1\}^{\mathbb{N}_0}, \sigma)$. In particular, the system $(X \vcentcolon= \overline{\sigma^{\mathbb{N}_0} 1_{B \cup \{0\}}}, \sigma)$ is minimal, the set $X \cap [1]_0$ is a clopen neighborhood of $1_{B \cup \{0\}}$, and $B = R(1_{B \cup \{0\}}, X \cap [1]_0) \subseteq A$.
    \end{enumerate}

Let $A \subseteq \mathbb{N}$.  The following statements are equivalent.
    \begin{enumerate}
        \item  The set $A$ is dynamically syndetic.

        \item  There exists a nonempty subset $B \subseteq A$ for which the point $1_B$ is uniformly recurrent in the full shift $(\{0, 1\}^{\mathbb{N}},\sigma)$.
    \end{enumerate}

Let $A \subseteq \mathbb{N}$ be dynamically central piecewise syndetic. For all $k \in \mathbb{N}$ and all $p_1, p_2, \ldots, p_k \in \mathbb{Q}[x]$ with $p_i(\mathbb{Z}) \subseteq \mathbb{Z}$ and $p_i(0) = 0$, there exist $x, y \in \mathbb{N}$ such that
    \begin{align}

        x, y, x + p_1(y), \ldots, x + p_k(y) \in A.
    \end{align}

Let $A \subseteq \mathbb{N}$.  The following conditions are equivalent to the set $A$ being thickly syndetic ($A \in \mathcal{PS}^*$):
    \begin{enumerate}
        \item
        for all $B \in d\mathcal{S}$, the set $A \cap B \in d\mathcal{S}$;

        \item
        for all $B \in d\mathcal{T}$, the set $A \cap B \in d\mathcal{T}$;

        \item
        for all $B \in \mathcal{PS}$, the set $A \cap B \in \mathcal{PS}$;

        \item for all $B \in \mathcal{PS}^*$, the set $A \cap B \in \mathcal{PS}^*$.
    \end{enumerate}
    Thus, the family $\mathcal{PS}^*$ is the largest family of sets that satisfies any one condition (equivalently, all conditions).  Moreover, if the set $A$ is thickly syndetic, then
    \begin{enumerate}
    \setcounter{enumi}{4}
        \item
        for all $B \in dc\mathcal{S}$, the set $A \cap B \in dc\mathcal{S}$;

        \item
        for all $B \in dc\mathcal{T}$, the set $A \cap B \in dc\mathcal{T}$;

        \item
        for all $B \in dc\mathcal{PS}$, the set $A \cap B \in dc\mathcal{PS}$;

        \item for all $B \in dc\mathcal{PS}^*$, the set $A \cap B \in dc\mathcal{PS}^*$.
    \end{enumerate}

Let $A \subseteq \mathbb{N}$.  The set $A$ is dynamically thick if and only if there exist a robustly syndetic collection $\mathscr{C}$ of subsets of $\mathbb{N}$ and, for each $B \in \mathscr{C}$, a thick set $H_B \subseteq \mathbb{N}$ such that
\begin{align}

    A = \bigcup_{B \in \mathscr{C}} \big( B \cap H_B\big).
\end{align}
